public class AbstractCategoryItemRenderer_getLegendItems_TriageGen2Test {

    @Spy
    private AbstractCategoryItemRenderer renderer;

    @Spy
    private CategoryPlot plot;

    @Spy
    private CategoryDataset dataset;

    @Before
    public void setUp() {
        renderer.setPlot(plot);
    }

    @Test
    public void testGetLegendItems_NullDataset() {
        int index = 0;
        when(plot.getIndexOf(renderer)).thenReturn(index);
        when(plot.getDataset(index)).thenReturn(null);

        LegendItemCollection result = renderer.getLegendItems();

        assertNotNull(result);
        assertEquals(0, result.size());
    }

    @Test
    public void testGetLegendItems_AscendingOrder_WithItems() {
        int index = 0;
        int seriesCount = 3;

        when(plot.getIndexOf(renderer)).thenReturn(index);
        when(plot.getDataset(index)).thenReturn(dataset);
        when(plot.getRowRenderingOrder()).thenReturn(SortOrder.ASCENDING);
        when(dataset.getRowCount()).thenReturn(seriesCount);

        // Mock visibility and legend items
        // Series 0: Visible, Item exists
        // Series 1: Not visible
        // Series 2: Visible, Item exists
        when(renderer.isSeriesVisibleInLegend(0)).thenReturn(true);
        when(renderer.getLegendItem(index, 0)).thenReturn(mock(LegendItem.class));

        when(renderer.isSeriesVisibleInLegend(1)).thenReturn(false);

        when(renderer.isSeriesVisibleInLegend(2)).thenReturn(true);
        when(renderer.getLegendItem(index, 2)).thenReturn(mock(LegendItem.class));

        // Series 1 (if it were visible) returns null to test null check
        // But we only call getLegendItem if isSeriesVisibleInLegend is true

        LegendItemCollection result = renderer.getLegendItems();

        assertEquals(2, result.size());
        verify(renderer, atLeastOnce()).isSeriesVisibleInLegend(0);
        verify(renderer, atLeastOnce()).isSeriesVisibleInLegend(1);
        verify(renderer, atLeastOnce()).isSeriesVisibleInLegend(2);
    }

    @Test
    public void testGetLegendItems_DescendingOrder_WithItems() {
        int index = 1;
        int seriesCount = 2;

        when(plot.getIndexOf(renderer)).thenReturn(index);
        when(plot.getDataset(index)).thenReturn(dataset);
        when(plot.getRowRenderingOrder()).thenReturn(SortOrder.DESCENDING);
        when(dataset.getRowCount()).thenReturn(seriesCount);

        // Series 1: Visible, Item exists
        when(renderer.isSeriesVisibleInLegend(1)).thenReturn(true);
        when(renderer.getLegendItem(index, 1)).thenReturn(mock(LegendItem.class));

        // Series 0: Visible, Item is null (testing the null check branch)
        when(renderer.isSeriesVisibleInLegend(0)).thenReturn(true);
        when(renderer.getLegendItem(index, 0)).thenReturn(null);

        LegendItemCollection result = renderer.getLegendItems();

        assertEquals(1, result.size());
        // Verify order: Descending means loop starts from seriesCount - 1
        // We check if getLegendItem was called with index 1 first
        verify(renderer).getLegendItem(index, 1);
        verify(renderer).getLegendItem(index, 0);
    }

    @Test
    public void testGetLegendItems_Ascending_WithNullItem() {
        int index = 0;
        int seriesCount = 1;

        when(plot.getIndexOf(renderer)).thenReturn(index);
        when(plot.getDataset(index)).thenReturn(dataset);
        when(plot.getRowRenderingOrder()).thenReturn(SortOrder.ASCENDING);
        when(dataset.getRowCount()).thenReturn(seriesCount);

        when(renderer.isSeriesVisibleInLegend(0)).thenReturn(true);
        when(renderer.getLegendItem(index, 0)).thenReturn(null);

        LegendItemCollection result = renderer.getLegendItems();

        assertEquals(0, result.size());
    }
}
